function RoomCard({room,owner,invitation,session}){const[open,setOpen]=useState(false);if(!room)return null;return <article className="room-card"><div className="room-card-top"><span className="room-badge">PRIVATE ROOM</span><span className={room.status==="active"?"room-live":"room-offline"}>● {room.status}</span></div><h3>{room.name}</h3><p>{room.description||"A private AMORA space."}</p><div className="room-capabilities"><span>Chat {room.chat_enabled?"on":"off"}</span><span>Voice {room.voice_enabled?"on":"off"}</span><span>Video {room.video_enabled?"on":"off"}</span></div>{owner?<small>Only invited members with active access can enter.</small>:<small>Invitation accepted · Active subscription required.</small>}<div className="room-actions"><button className="primary" onClick={()=>setOpen(true)}>{owner?"Open room":"Enter room"}</button></div>{open&&<RoomInterface room={room} session={session} onClose={()=>setOpen(false)}/>}</article>}

